using GameplayCore.Damage; using GameplayCore.Entities; using ZombieWar.Features.Targeting.Domain; using ZombieWar.Features.Boss.Controller; using ZombieWar.Features.Boss.Domain;
namespace ZombieWar.Integration.Boss { public sealed class BossCombatBridge:IDamageable,ITargetCandidate { private readonly BossController _controller;public BossCombatBridge(BossController controller){_controller=controller;}public EntityId EntityId=>_controller.EntityId;public bool IsAlive=>_controller.IsAlive;public bool IsTargetable=>_controller.IsTargetable;public TargetPoint Position{get{BossPoint p=_controller.Position;return new TargetPoint(p.X,p.Y,p.Z);}}public void ApplyDamage(DamageInfo damage)=>_controller.ReceiveDamage(damage); } }
